/**
 * Reading and writing one text file.
 *
 * Two properties matter more than speed here: a read must refuse anything it
 * cannot represent faithfully (binary, invalid UTF-8, oversized) instead of
 * handing the editor mangled text, and a write must never leave a half-written
 * file behind. Both are enforced in this module, below the route.
 */

import { chmod, mkdir, open, readFile, rename, rm, stat } from 'node:fs/promises'
import { dirname } from 'node:path'
import { MAX_TEXT_BYTES } from './protocol.js'

/** The UTF-8 byte-order mark: stripped on read, restored on write. */
const BOM = '\uFEFF'

/** Distinguishes same-millisecond writes from this process to one target. */
let temporarySequence = 0

/**
 * File identity used for optimistic-concurrency checks.
 *
 * The modification time alone is too coarse to be an identity: two writes
 * inside one millisecond, or a filesystem whose timestamps only move every two
 * seconds, would report the same version for different content. The byte size
 * joins it, so any write that changes the file's length always moves the
 * version.
 * @param {import('node:fs').Stats} info - result of `stat`.
 * @returns {{ version: string, bytes: number }} the version string and byte size.
 */
export function versionOf(info) {
  return { version: `${Math.round(info.mtimeMs)}:${info.size}`, bytes: info.size }
}

/**
 * Stat one path as a regular file.
 * @param {string} path - absolute path.
 * @returns {Promise<import('node:fs').Stats | undefined>} the stat, or undefined
 *   when it is absent or not a regular file.
 */
export async function statRegular(path) {
  try {
    const info = await stat(path)
    return info.isFile() ? info : undefined
  } catch (error) {
    if (error?.code === 'ENOENT' || error?.code === 'ENOTDIR') return undefined
    throw error
  }
}

/**
 * Read one text file, refusing rather than mangling anything non-text.
 * @param {string} target - absolute path.
 * @returns {Promise<{ value?: object, code?: string, message?: string }>}
 *   `{ value }` on success, or `{ code, message }` on refusal.
 */
export async function readText(target) {
  const info = await statRegular(target)
  if (info === undefined) {
    return { code: 'not-found', message: 'No regular file exists at that path.' }
  }
  if (info.size > MAX_TEXT_BYTES) {
    return {
      code: 'too-large',
      message: `That file is ${Math.round(info.size / 1024)} KiB; the editor opens files up to ${Math.round(MAX_TEXT_BYTES / 1024 / 1024)} MiB.`,
    }
  }
  const buffer = await readFile(target)
  if (buffer.includes(0)) {
    return { code: 'not-text', message: 'That file looks binary — it contains NUL bytes.' }
  }
  let decoded
  try {
    // `ignoreBOM: true` keeps the mark in the decoded string: the default
    // decoder drops it silently, which would make "did this file have one?"
    // unanswerable and a save unable to put the same bytes back.
    decoded = new TextDecoder('utf-8', { fatal: true, ignoreBOM: true }).decode(buffer)
  } catch {
    return { code: 'not-text', message: 'That file is not valid UTF-8 text.' }
  }
  // A byte-order mark is an encoding artefact, not the file's first character.
  // It is reported separately so a save can put the same bytes back: dropping
  // it silently would rewrite the file's encoding, which tools such as
  // Windows PowerShell 5 depend on.
  const bom = decoded.startsWith(BOM)
  return {
    value: {
      absolutePath: target,
      text: bom ? decoded.slice(BOM.length) : decoded,
      bom,
      ...versionOf(info),
    },
  }
}

/**
 * Flush a directory entry, so the rename that published a write survives a
 * power loss. Windows cannot open a directory for this, and there the rename is
 * already as durable as the platform offers; a failure is therefore ignored.
 * @param {string} path - directory to flush.
 */
async function syncDirectory(path) {
  let handle
  try {
    handle = await open(path, 'r')
    await handle.sync()
  } catch {
    /* this platform does not support flushing a directory */
  } finally {
    if (handle !== undefined) await handle.close().catch(() => {})
  }
}

/**
 * Write one text file through a same-directory temporary file and a rename, so a
 * failed or interrupted save never leaves a half-written file behind.
 *
 * The temporary file is flushed before the rename, and the directory after it,
 * so a power loss cannot publish an empty or partial file. The target's
 * permission bits are copied onto the temporary file first, because a brand new
 * file would otherwise replace them with the directory's defaults.
 * @param {string} target - absolute path.
 * @param {string} text - complete new content, without a byte-order mark.
 * @param {string | undefined} expectedVersion - version the editor started from, when it has one.
 * @param {unknown} force - overwrite even when the version moved.
 * @param {unknown} bom - whether the file arrived with a byte-order mark, which is restored.
 * @returns {Promise<{ value?: object, code?: string, message?: string }>}
 *   `{ value }` on success, or `{ code, message }` on refusal.
 */
export async function writeText(target, text, expectedVersion, force, bom) {
  const body = bom === true ? BOM + text : text
  const bytes = Buffer.byteLength(body, 'utf8')
  if (bytes > MAX_TEXT_BYTES) {
    return {
      code: 'too-large',
      message: `That content is ${Math.round(bytes / 1024)} KiB, above the editor's limit.`,
    }
  }

  const before = await statRegular(target)
  if (before !== undefined) {
    // A read-only target is refused rather than probed with a rename that would
    // fail: the reason belongs in the answer, not in a generic I/O error.
    if ((before.mode & 0o222) === 0) {
      return {
        code: 'read-only',
        message: 'That file is read-only, so the editor cannot save over it.',
      }
    }
    if (force !== true) {
      // A save with no version is a save whose author never saw the file: it can
      // only be an overwrite, and an overwrite of unknown content is how a file
      // gets emptied by a keystroke. Refusing it is the whole point of the check.
      if (typeof expectedVersion !== 'string') {
        return {
          code: 'version-required',
          message:
            'That file already exists and this save carries no version, so the editor cannot tell whether it would overwrite newer content.',
        }
      }
      if (versionOf(before).version !== expectedVersion) {
        return {
          code: 'version-conflict',
          message:
            'The file changed on disk after the editor read it. Reload to pick up the new content, or save again to overwrite it.',
        }
      }
    }
  }

  await mkdir(dirname(target), { recursive: true })
  // The sequence keeps two writes to one target from meeting on one temp path
  // when they land in the same millisecond; the pid keeps two processes apart.
  const temporary = `${target}.dsh-editor-${process.pid}-${Date.now()}-${temporarySequence++}.tmp`
  const handle = await open(temporary, 'w')
  try {
    await handle.writeFile(body, 'utf8')
    await handle.sync()
  } finally {
    await handle.close()
  }
  // A fresh file carries the directory's defaults, not the target's bits; on
  // Windows that includes the read-only attribute.
  if (before !== undefined) await chmod(temporary, before.mode & 0o777).catch(() => {})
  try {
    await rename(temporary, target)
  } catch (error) {
    await rm(temporary, { force: true }).catch(() => {})
    throw error
  }
  await syncDirectory(dirname(target))
  return { value: { absolutePath: target, ...versionOf(await stat(target)) } }
}
